// Separate vector insignia allows position, size, rotation, color and visibility edits.
export function drawDepotInsignia(c,mark,width,height,armband=false){if(mark?.visible===false)return;const size=width*(mark?.size??.22),x=-width/2+width*(mark?.x??.32),y=-height/2+height*(mark?.y??.5);c.save();c.translate(x,y);c.rotate((mark?.rotation||0)*Math.PI/180);c.globalAlpha*=mark?.opacity??.85;if(armband){const band=c.createLinearGradient(-size,0,size,0);band.addColorStop(0,'#451710');band.addColorStop(.3,mark.bandColor||'#ab211b');band.addColorStop(.75,mark.bandColor||'#ab211b');band.addColorStop(1,'#4c1811');c.fillStyle=band;c.beginPath();c.moveTo(-size*.82,-size*.45);c.quadraticCurveTo(0,-size*.56,size*.82,-size*.45);c.lineTo(size*.82,size*.45);c.quadraticCurveTo(0,size*.55,-size*.82,size*.45);c.closePath();c.fill();c.fillStyle='#e6e0ce';c.beginPath();c.arc(0,0,size*.46,0,Math.PI*2);c.fill()}c.rotate((armband?45:mark?.tilt??45)*Math.PI/180);const r=size*(armband ? .23 : .42);c.strokeStyle=mark?.color||(armband?'#171410':'#dfddcb');c.lineWidth=r*.36;c.lineCap='butt';c.lineJoin='miter';c.beginPath();c.moveTo(0,-r);c.lineTo(0,r);c.moveTo(-r,0);c.lineTo(r,0);c.moveTo(0,-r);c.lineTo(r,-r);c.moveTo(r,0);c.lineTo(r,r);c.moveTo(0,r);c.lineTo(-r,r);c.moveTo(-r,0);c.lineTo(-r,-r);c.stroke();c.restore();return {x,y,size}}
export function createDepotScene(){const air=createAtmosphere();function cover(c,im,scale=1){if(!im?.naturalWidth)return;const r=Math.max(960/im.naturalWidth,540/im.naturalHeight)*scale;c.drawImage(im,480-im.naturalWidth*r/2,270-im.naturalHeight*r/2,im.naturalWidth*r,im.naturalHeight*r)}
return {paint(c,age,f,sprites,options={}){const s=depotState(age,f);c.canvas.sceneAssets=[];if(!options.transparent){c.fillStyle='#251e13';c.fillRect(0,0,960,540);c.save();c.filter=`blur(${s.roomBlur}px) brightness(${f.depotBrightness}) saturate(${f.depotSaturation})`;cover(c,sprites.depotRoom,s.backScale);c.restore();recordSceneAsset(c,{id:'depot-room',kind:'depotRoom',name:'Warm supply depot',assetSlot:'depotRoom'},[0,0,960,540]);air.paint(c,age,{...f.depotHaze,density:(f.depotHaze.density||0)*(1-.3*s.pull)});}
if(!options.transparent){const floor=c.createLinearGradient(0,340,0,540);floor.addColorStop(0,'#44352400');floor.addColorStop(1,'#30251f');c.fillStyle=floor;c.fillRect(0,340,960,200);c.save();c.filter='blur(3px)';c.translate(f.depotFlagX??40,f.depotFlagY??270);c.scale(f.depotFlagScale??1,f.depotFlagScale??1);c.rotate(-.12);c.fillStyle='#661b15';c.fillRect(-70,-80,180,160);recordSceneAsset(c,{id:'depot-flag',kind:'depotFlag',name:'Corner flag'},[-70,-80,180,160]);drawDepotInsignia(c,{x:.5,y:.5,size:.55,color:'#13110e',opacity:.8,visible:true},180,160,true);c.restore()}
for(const depth of ['back','mid','near','people','front'])for(const stored of f.depotObjects){if(stored.depth!==depth)continue;const o=sampleKeys(stored,age),alpha=depotEnvelope(age,o),im=sprites[o.slot];if(!alpha||!im?.naturalWidth)continue;const texture=o.type==='person'?depotFigureTexture(im,o.slot):im;const p=depotPlacement(o,s,f);c.save();c.translate(p.x,p.y);c.scale(p.scale,p.scale);c.rotate(p.rotation*Math.PI/180);c.globalAlpha=alpha;c.filter=`blur(${o.blur||0}px) brightness(${o.brightness??1})`;if(o.type==='crate'){c.save();c.filter='blur(7px)';c.fillStyle='#080705b0';c.beginPath();c.ellipse(0,o.height*.44,o.width*.39,13,0,0,7);c.fill();c.restore()}c.drawImage(texture,-o.width/2,-o.height/2,o.width,o.height);recordSceneAsset(c,{id:'depot:'+o.id,kind:'depotObject',name:o.name,objectId:o.id,assetSlot:o.slot},[-o.width/2,-o.height/2,o.width,o.height],alphaFor(texture));c.filter='none';if(o.type!=='person'&&o.mark&&o.mark.visible!==false){drawDepotInsignia(c,o.mark,o.width,o.height,o.type==='person');const mark=o.mark,size=o.width*mark.size,x=-o.width/2+o.width*mark.x,y=-o.height/2+o.height*mark.y;recordSceneAsset(c,{id:'depot-mark:'+o.id,kind:'depotInsignia',name:(o.type==='person'?'Armband · ':'Crate marking · ')+o.name,objectId:o.id,assetSlot:o.slot},[x-size*.9,y-size*.7,size*1.8,size*1.4])}c.restore()}
if(!options.transparent){const vig=c.createRadialGradient(480,300,150,480,270,650);vig.addColorStop(0,'#0000');vig.addColorStop(1,'#090805a0');c.fillStyle=vig;c.fillRect(0,0,960,540);}return s},air}}
